import random, copy
from collections import OrderedDict
from boltons.dictutils import OrderedMultiDict as O
from boltons.cacheutils import LRU
from boltons.setutils import IndexedSet as I
# OMD vs list of pairs
for t in range(3000):
    o=O(); ref=[]
    for _ in range(12):
        op=random.randint(0,7); k=random.choice('abc'); v=random.randint(0,9)
        try:
            if op==0: o.add(k,v); ref.append((k,v))
            elif op==1: o[k]=v; ref=[p for p in ref if p[0]!=k]; ref.append((k,v))
            elif op==2:
                if any(p[0]==k for p in ref):
                    r=o.pop(k); exp=[p for p in ref if p[0]==k][-1][1]; ref=[p for p in ref if p[0]!=k]; assert r==exp,('pop',r,exp)
            elif op==3:
                if any(p[0]==k for p in ref):
                    r=o.poplast(k); idx=max(i for i,p in enumerate(ref) if p[0]==k); exp=ref.pop(idx)[1]; assert r==exp,('poplast',r,exp)
            elif op==4:
                if any(p[0]==k for p in ref): del o[k]; ref=[p for p in ref if p[0]!=k]
            elif op==5: o.update_extend([(k,v)]); ref.append((k,v))
            elif op==6: o=copy.deepcopy(o) if v%2 else o.copy()
            elif op==7:
                if ref:
                    r=o.popitem(); exp=ref[-1]; ref=[p for p in ref if p[0]!=exp[0]]; assert r==exp,('popitem',r,exp)
        except AssertionError as e: print(e, ref); raise
        assert list(o.items(multi=True))==ref, (op,k,v,list(o.items(multi=True)),ref)
        keys=list(OrderedDict.fromkeys(p[0] for p in ref))
        assert list(o.keys())==keys,('keys',list(o.keys()),keys)
        for kk in keys: assert o[kk]==[p for p in ref if p[0]==kk][-1][1] and o.getlist(kk)==[p[1] for p in ref if p[0]==kk]
        assert len(o)==len(keys)
print('omd ok')
for t in range(2000):
    n=random.randint(1,5); c=LRU(max_size=n); ref=OrderedDict()
    for _ in range(30):
        k=random.randint(0,7); op=random.randint(0,3)
        if op==0:
            c[k]=k; ref[k]=k; ref.move_to_end(k)
            while len(ref)>n: ref.popitem(last=False)
        elif op==1:
            if k in ref: assert c[k]==k; ref.move_to_end(k)
            else: assert c.get(k) is None
        elif op==2:
            if k in ref: del c[k]; del ref[k]
        else: assert (k in c)==(k in ref)
        assert sorted(c)==sorted(ref), (op,k,sorted(c),list(ref))
print('lru ok')
for t in range(3000):
    s=I(); ref=[]
    for _ in range(25):
        op=random.randint(0,5); x=random.randint(0,12)
        if op==0: s.add(x); ref.append(x) if x not in ref else 0
        elif op==1: s.discard(x); ref.remove(x) if x in ref else 0
        elif op==2 and ref:
            i=random.randrange(-len(ref),len(ref)); assert s.pop(i)==ref.pop(i)
        elif op==3:
            if x in ref: assert s.index(x)==ref.index(x)
        elif op==4 and ref:
            i=random.randrange(-len(ref),len(ref)); assert s[i]==ref[i],('get',i,s[i],ref[i],ref)
        elif op==5: o=set(random.sample(range(13),5)); assert list(s|o)[:len(ref)]==ref and set(s&o)==set(ref)&o and list(s-o)==[r for r in ref if r not in o]
        assert list(s)==ref and len(s)==len(ref), (op,x,list(s),ref)
print('iset ok')
"

